window.LabFlowDocs=[{"id":"readme","title":"LabFlow","path":"README.md","group":"Overview","updated":"05 Aug 2026","status":"Current","description":"LabFlow is a static research workspace designed by **Matteo Ginesi** to make laboratory projects easier to plan, inspect, compare and report. The proof of concept runs from checked-in HTML, CSS and JavaScript, uses no CDN, sends no automatic request and retains no browser state after reload."},{"id":"project","title":"Project model and architecture","path":"docs/PROJECT.md","group":"Overview","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow turns the structure of laboratory work into an inspectable product model. It demonstrates how a researcher can move from a project objective to prepared materials, experiments, evidence, analysis and export without losing identifiers, provenance or human control."},{"id":"ui-ux-guidelines","title":"UI and interaction guidelines","path":"docs/UI_UX_GUIDELINES.md","group":"Overview","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow should feel like calibrated laboratory instrumentation: compact, sober and precise. Small radii, low controls, clear separators, dense tables and restrained accents support scanning. Decoration is secondary to identifiers, state, evidence and next actions."},{"id":"pipeline-catalog","title":"Pipeline catalog","path":"docs/PIPELINE_CATALOG.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow pipelines describe **how work is organised and verified**, not how pages are styled. A simple example may provide navigation metadata only; a primary domain pipeline can additionally define record boundaries, sections, completion rules, expected evidence, mappings and export policy. Shared HTML, CSS and report engines remain application components rather than being copied into YAML."},{"id":"pipeline-chose","title":"CHOSE Perovskite Workflow","path":"docs/PIPELINE_CHOSE.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"The CHOSE pipeline is LabFlow’s primary domain workflow for perovskite research. It turns reusable laboratory definitions into traceable experiment executions, validated result sets and evidence-linked reports without mixing planned and actual data."},{"id":"pipeline-quick","title":"Quick Measurement Review","path":"docs/PIPELINE_QUICK.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"Quick Measurement Review is a deliberately small example pipeline. It proves that LabFlow can host a focused scientific review without copying the CHOSE workflow or changing the shared application shell."},{"id":"pipelines-and-data","title":"Pipelines, records and provenance","path":"docs/PIPELINES_AND_DATA.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"A pipeline describes workflow: ordered steps, labels, expected outputs and the shared project view used by each step. It does not duplicate HTML, component styling or export layouts. Pipeline steps organise work around domain records; they never replace the identities of a Process, Experiment, Result Set or Report."},{"id":"robotics","title":"Robotics capability","path":"docs/ROBOTICS.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"Robotics is a top-level LabFlow capability, parallel to AI & Models. It demonstrates how a laboratory can simulate, configure, execute and document robotic operations while preserving the same Project, Process, Experiment and evidence model used elsewhere in the platform."},{"id":"ai-ml-foundation","title":"AI, machine learning, deep learning and Vision foundation","path":"docs/AI_ML_FOUNDATION.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow treats AI readiness as a consequence of ordinary laboratory work. Researchers continue to use **Workspace → Project → Process → Experiment**; LabFlow captures stable identifiers, units, provenance, files, transformations, labels and outcomes behind that workflow."},{"id":"ai-reports-and-export","title":"Lab Assistant, diagrams, reports and export","path":"docs/AI_REPORTS_AND_EXPORT.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"Ask LabFlow is the knowledge-facing part of the wider AI-ready foundation. The **AI & Models** workspace also demonstrates dataset snapshots, model versions, training runs and prediction review. These capabilities share evidence, provenance and human-control rules but remain different scientific record types. See `AI_ML_FOUNDATION.md`."},{"id":"theme-integration","title":"Theme integration","path":"docs/THEME_INTEGRATION.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow uses semantic tokens so components describe purpose instead of choosing isolated colors. Content defaults to light while the application shell remains dark. Eight palettes tint accents and shell depth without changing scientific status meanings."},{"id":"javascript-logging","title":"JavaScript logging and diagnostics","path":"docs/JAVASCRIPT_LOGGING.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow includes one local JavaScript diagnostic system for the whole static POC. It writes structured entries to the browser console and keeps a bounded in-memory copy for inspection. It never transmits, persists or uploads logs."},{"id":"validation-checklist","title":"Validation checklist","path":"docs/VALIDATION_CHECKLIST.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"Use this checklist after changes to behavior, data contracts, pipelines, documentation, themes, diagrams or exporters. Refresh every affected checked-in browser snapshot before testing."}];
